import {canonicalSha256} from '../core/canonical-json.mjs';
export function clusterInstincts(instincts=[]){const groups=new Map();for(const item of [...instincts].sort((a,b)=>a.id.localeCompare(b.id))){const key=canonicalSha256({tenantId:item.scope?.tenantId??null,projectId:item.scope?.projectId??null,trustDomain:item.trustDomain??null,mechanism:item.mechanism,outcome:item.outcome??'unknown'});if(!groups.has(key))groups.set(key,[]);groups.get(key).push(item);}return [...groups.values()].map(members=>{const sorted=[...members].sort((a,b)=>a.id.localeCompare(b.id));const payload={mechanism:sorted[0].mechanism,outcome:sorted[0].outcome??'unknown',scope:sorted[0].scope,trustDomains:[...new Set(sorted.map(x=>x.trustDomain))].sort(),instinctIds:sorted.map(x=>x.id),confidence:sorted.reduce((sum,x)=>sum+x.confidence,0)/sorted.length};return Object.freeze({...payload,clusterId:`cluster-${canonicalSha256(payload).slice(0,16)}`,clusterSha256:canonicalSha256(payload),members:sorted});}).sort((a,b)=>a.clusterId.localeCompare(b.clusterId));}
